@if($form==='product')<form wire:submit="saveProduct"><div class="row g-3">@foreach(['name'=>'Product name','stock_key'=>'Shared stock pool key','pack_quantity'=>'Pack quantity (grams for honey, 1 for snacks)','price'=>'Selling price (PKR)','low_stock'=>'Low stock threshold (base units)'] as $field=>$label)<div class="col-md-6"><label class="form-label" for="product-{{ $field }}">{{ $label }}</label><input id="product-{{ $field }}" class="form-control" wire:model="product.{{ $field }}" type="{{ in_array($field,['pack_quantity','price','low_stock'])?'number':'text' }}" @if($field==='price') step="0.01" min="0" @endif required></div>@endforeach<div class="col-md-6"><label class="form-label" for="kind">Category</label><select id="kind" class="form-select" wire:model="product.kind"><option value="honey">Honey (grams)</option><option value="snack">Packaged snacks (whole units)</option></select></div></div><p class="small muted mt-3">For example, 500 g and 1,000 g Sidr honey use the same pool key <code>sidr-honey</code>. Pool keys accept letters, numbers, dashes and underscores.</p><button class="btn btn-peach" wire:loading.attr="disabled">Save product</button></form>
@else<form wire:submit="receiveBatch"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="batch-pool">Stock pool</label><select id="batch-pool" class="form-select" wire:model="batch.stock_key" required><option value="">Choose pool</option>@foreach($products->unique('stock_key') as $p)<option value="{{ $p->stock_key }}">{{ $p->stock_key }} ({{ $p->kind==='honey'?'grams':'whole units' }})</option>@endforeach</select></div>@foreach(['reference'=>'Unique batch reference','received_on'=>'Stock-in date','original_quantity'=>'Original sellable quantity (grams or units)','purchase'=>'Purchase cost (PKR)','packaging'=>'Packaging cost (PKR)','branding'=>'Branding cost (PKR)','other'=>'Other direct costs (PKR)'] as $field=>$label)<div class="col-md-6"><label class="form-label" for="batch-{{ $field }}">{{ $label }}</label><input id="batch-{{ $field }}" class="form-control" wire:model="batch.{{ $field }}" type="{{ $field==='received_on'?'date':($field==='reference'?'text':'number') }}" @if(!in_array($field,['reference','received_on','original_quantity'])) step="0.01" min="0" @endif required></div>@endforeach</div><p class="small muted mt-3">Enter all costs once for the entire batch. Costs are allocated over the original sellable quantity and saved when dispatched. For 10 kg of honey, enter 10,000 grams.</p><button class="btn btn-peach" wire:loading.attr="disabled">Receive batch</button></form>@endif
